// job-ingest answers with ONE item carrying the whole queue. Fan it out so each
// application is its own item.
const res = $input.first().json;
if (!res || res.ok !== true) {
  throw new Error('job-ingest apply_queue failed: ' + JSON.stringify(res).slice(0, 300));
}
const queue = res.queue || [];
const skipped = res.skipped || [];

// skipped[] is the server saying it declined to queue something — a guard that
// held, not an error here. Log it and move on. Acting on it from n8n would mean
// re-deriving a decision the edge function already made, which is how two copies of
// a rule start disagreeing (CLAUDE.md keeps the receipts: the stale Garmin bridge,
// the duplicated BIA constants).
for (const s of skipped) {
  console.log('apply_queue skipped ' + (s && s.application_id) + ': ' + (s && s.reason));
}

// Empty is the normal steady state: everything approved has already been sent.
if (queue.length === 0) return [];

return queue.map((q) => ({ json: q }));

