// --- node body ---
// The last checkpoint before an email leaves for a real company.
//
// Every row here has already been guard-checked server-side and flipped to
// 'queued'. This node re-checks exactly ONE thing — the recipient — because that is
// the only field whose failure is unrecoverable. An application sent to the wrong
// address cannot be recalled, apologised for, or superseded.
//
// It transforms the body by nothing at all. No signature, no greeting, no footer,
// no wrapping: the body is human prose assembled from human-written modules and the
// closing module IS the sign-off. A second one reads as a bug to the person opening
// it. If you ever find yourself adding a .replace() below, stop and re-read this.
const out = [];
for (const item of $input.all()) {
  const app = item.json || {};
  const posting = app.posting || {};

  // The recipient is posting.apply_email and nothing else. Not the company domain,
  // not a guessed info@, not a fallback to the notify inbox — an application
  // arriving at the wrong company is worse than one that never arrives.
  const to = validateRecipient(posting.apply_email);
  const body = typeof app.body === 'string' ? app.body : '';

  let error = null;
  if (!to) {
    error =
      'refused to send: apply_email is missing or is not one plain address (' +
      String(posting.apply_email).slice(0, 120) +
      ')';
  } else if (!body.trim()) {
    error = 'refused to send: the stored application body is empty';
  }

  out.push({
    json: {
      application_id: app.application_id,
      // A refusal is reported as a failed attempt rather than dropped. Dropping it
      // would leave the row 'queued' forever and re-refuse it every 10 minutes in
      // silence; a recorded failure is a thing a human can see and fix.
      sendable: error === null,
      error: error,
      to: to || '',
      subject: applySubject(app),
      body: body,
      company: (posting && posting.company) || null,
      title: (posting && posting.title) || null,
    },
  });
}
return out;

