// --- node body ---
// Reached only from the Gmail node's SUCCESS output.
//
// Pairing is by pairedItem, not by position: the error output pulls failed sends
// out of this stream, so output-0 index i stops being upstream index i as soon as
// one fails — and here that offset would record "sent" against an application that
// was not sent, to a company that never heard from you.
const prepared = $('Prepare Application').all();

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const sent = items[i].json || {};
  const src = prepared[pairedSourceIndex(items[i].pairedItem, i)];
  const applicationId = src && src.json ? src.json.application_id : null;
  if (!applicationId) continue;

  out.push({
    json: {
      action: 'apply_result',
      user_id: $env.NEXUS_USER_ID,
      application_id: applicationId,
      ok: true,
      // The proof is the whole point of this row: a Gmail message id is the only
      // durable evidence that an application actually left, and the thread id is
      // what a reply from the company will arrive on.
      proof: {
        gmail_message_id: sent.id || sent.messageId || null,
        thread_id: sent.threadId || null,
      },
    },
  });
}
return out;

