// --- node body ---
// Two inputs land here and both mean the same thing: nothing was sent.
//
//   1. "Sendable?" false — this node refused the row (bad recipient, empty body).
//   2. the Gmail node's error output — Gmail refused it.
//
// n8n runs this node once per incoming branch, so each set is reported on its own.
// Either way the row is finalized as a failed attempt rather than left 'queued',
// because a row that silently re-fails every 10 minutes is indistinguishable from
// one that is working.
const prepared = $('Prepare Application').all();

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const j = items[i].json || {};
  const src = prepared[pairedSourceIndex(items[i].pairedItem, i)];
  const meta = (src && src.json) || {};
  const applicationId = meta.application_id || j.application_id || null;
  if (!applicationId) continue;

  const raw = j.error || meta.error || 'send failed with no error attached';
  const message = typeof raw === 'string' ? raw : raw.message || JSON.stringify(raw);

  out.push({
    json: {
      action: 'apply_result',
      user_id: $env.NEXUS_USER_ID,
      application_id: applicationId,
      ok: false,
      error: String(message).slice(0, 500),
    },
  });
}
return out;
